# ── NON-MEDICINAL BLACKLIST (Common English Phrases & Noise) ─────
# Words that might be preceded by "take", "give", "prescribe", etc., but are NOT medications.
NON_MEDICINAL_WORDS = {
    "even", "even if", "if", "as", "care", "rest", "bed rest", "food", "meals", "meal",
    "water", "fluids", "warm water", "milk", "tea", "coffee", "it", "this", "that", "these",
    "those", "them", "him", "her", "you", "they", "we", "he", "she", "i", "me", "my",
    "morning", "evening", "night", "afternoon", "day", "days", "time", "times", "hour", "hours",
    "week", "weeks", "month", "months", "year", "years", "daily", "daily basis", "good",
    "plenty", "diet", "light diet", "soft diet", "bland diet", "spicy food", "oily food",
    "fruits", "vegetables", "exercise", "walk", "walking", "sleep", "proper rest",
    "caution", "precautions", "test", "tests", "appointment", "visit", "consultation",
    "blood", "sugar", "pressure", "temperature", "fever", "pain", "cough", "cold",
    "headache", "vomiting", "nausea", "sample", "report", "reports", "injection",
    "tablet", "tablets", "capsule", "capsules", "syrup", "medicine", "medicines", "drug", "drugs",
    "dose", "doses", "dosage", "prescribed", "start", "stop", "continue", "review", "regularly",
    "properly", "slowly", "carefully", "immediately", "soon", "later", "whenever", "wherever",
    "sometime", "sometimes", "always", "never", "only", "also", "just", "very", "much",
    "little", "more", "less", "few", "lot", "lots", "plenty of", "warm", "hot", "cold",
    "salt water", "steam", "gargle", "gargles", "dressing", "bandage",
}


def lookup(name: str) -> dict | None:
    """Look up a medicine by exact key, cleaned token, or generic name. Returns info dict or None."""
    if not name:
        return None
    key = name.strip().lower()

    # 1. Exact match
    if key in COMMON_MEDICINES:
        return COMMON_MEDICINES[key]

    # 2. Strip common suffix words like "tablet", "capsule", "syrup", "drops", etc.
    cleaned = re.sub(r"\b(?:tablet|tablets|tab|capsule|capsules|cap|syrup|syp|suspension|drops|drop|gel|ointment|cream|inhaler|injection|inj)\b", "", key).strip()
    if cleaned in COMMON_MEDICINES:
        return COMMON_MEDICINES[cleaned]

    # 3. Search by generic name match
    for med_key, info in COMMON_MEDICINES.items():
        if info.get("generic", "").lower() == key or info.get("generic", "").lower() == cleaned:
            return info

    # 4. First word match (e.g. "combiflam 1" -> "combiflam")
    first_word = key.split()[0] if key else ""
    if first_word in COMMON_MEDICINES:
        return COMMON_MEDICINES[first_word]

    return None


def get_route_and_instructions(name: str) -> dict:
    """Look up route and instructions for a medicine from the catalog.
    Returns dict with 'route' and 'instructions' keys (empty strings if not found).
    Used by normalizer and LLM refiner to auto-enrich medication entries.
    """
    info = lookup(name)
    if info:
        return {
            "route": info.get("route", ""),
            "instructions": info.get("instructions", ""),
        }
    return {"route": "", "instructions": ""}

